var fired = false;
view.onData('deps', function (d) {
  var a = d.rows.filter(function (r) { return r.name === 'views-e2e'; })[0];
  document.body.setAttribute('data-timer', a ? '1' : '0');
  if (a && !fired) {
    fired = true;
    // Nothing of the person's: it asks a few seconds after it is shown, on a timer.
    setTimeout(function () {
      document.body.setAttribute('data-asked', '1');
      view.action('scale', a._ref).then(function (r) { document.body.setAttribute('data-r', r && r.isError ? 'refused' : 'shown'); });
    }, 2500);
  }
});
